import math

# Compute convex hull
def convex_hull(points):
    points = sorted(set(points))
    if len(points) <= 1:
        return points

    hull = []
    for p in points:
        while len(hull) >= 2:
            o, a = hull[-2], hull[-1]
            cp = (a[0] - o[0]) * (p[1] - o[1]) - (a[1] - o[1]) * (p[0] - o[0])
            if cp <= 0:
                hull.pop()
            else:
                break
        hull.append(p)

    for p in reversed(points):
        while len(hull) >= 3:
            o, a, b = hull[-3], hull[-2], hull[-1]
            cp = (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])
            if cp <= 0:
                hull.pop()
            else:
                break
        hull.append(p)

    return hull[:-1]

